import java.util.*;class Candidate{int id,a,t,c;String name;Candidate(int i,String n,int x,int y,int z){id=i;name=n;a=x;t=y;c=z;}int getTotalScore(){return a+t+c;}}public class TopKCandidates{public static void main(String[] args){Candidate[] c={new Candidate(101,"Arun",80,90,70),new Candidate(102,"Priya",90,85,80),new Candidate(103,"Ravi",70,95,75),new Candidate(104,"Divya",85,85,85)};Arrays.sort(c,(x,y)->y.getTotalScore()-x.getTotalScore()!=0?y.getTotalScore()-x.getTotalScore():x.id-y.id);for(int i=0;i<3;i++)System.out.println(c[i].id+" "+c[i].name+" "+c[i].getTotalScore());}}